class GenerationError(Exception):
    """Unrecoverable input problem (unbalanced braces, missing \\val key, ...)."""


# ---------------------------------------------------------------------------
# Low-level LaTeX scanning helpers
# ---------------------------------------------------------------------------

def strip_comments(s: str) -> str:
    """Drop % comments with TeX semantics (the newline and next line's indent go too)."""
    out, i, n = [], 0, len(s)
    while i < n:
        c = s[i]
        if c == "\\" and i + 1 < n:
            out.append(s[i:i + 2])
            i += 2
            continue
        if c == "%":
            j = s.find("\n", i)
            if j == -1:
                break
            i = j + 1
            while i < n and s[i] in " \t":
                i += 1
            continue
        out.append(c)
        i += 1
    return "".join(out)


def read_group(s: str, i: int) -> tuple[str, int]:
    """s[i] == '{'; return (content, index after the matching '}')."""
    if i >= len(s) or s[i] != "{":
        raise GenerationError(f"expected '{{' at offset {i}: {s[i:i + 40]!r}")
    depth, j = 0, i
    while j < len(s):
        c = s[j]
        if c == "\\":
            j += 2
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return s[i + 1:j], j + 1
        j += 1
    raise GenerationError(f"unbalanced braces starting at: {s[i:i + 60]!r}")


def skip_ws(s: str, i: int, newlines: bool = True) -> int:
    chars = " \t\r\n" if newlines else " \t"
    while i < len(s) and s[i] in chars:
        i += 1
    return i


def read_arg(s: str, i: int) -> tuple[str, int]:
    """Read one mandatory argument: a {group} or a single token."""
    i = skip_ws(s, i)
    if i >= len(s):
        raise GenerationError("missing macro argument at end of input")
    if s[i] == "{":
        return read_group(s, i)
    if s[i] == "\\":
        m = re.match(r"\\([A-Za-z]+|.)", s[i:])
        return m.group(0), i + len(m.group(0))
    return s[i], i + 1


def read_optional(s: str, i: int) -> tuple[str | None, int]:
    """Read an optional [..] argument (braces inside are respected)."""
    j = skip_ws(s, i, newlines=False)
    if j >= len(s) or s[j] != "[":
        return None, i
    depth, k = 0, j
    while k < len(s):
        c = s[k]
        if c == "\\":
            k += 2
            continue
        if c == "{":
            _, k = read_group(s, k)
            continue
        if c == "[":
            depth += 1
        elif c == "]":
            depth -= 1
            if depth == 0:
                return s[j + 1:k], k + 1
        k += 1
    raise GenerationError(f"unterminated optional argument: {s[j:j + 60]!r}")


def find_env_end(s: str, start: int, name: str) -> tuple[int, int]:
    """Return (start, end) of the \\end{name} matching a \\begin{name} ending at `start`."""
    pat = re.compile(r"\\(begin|end)\{" + re.escape(name) + r"\}")
    depth = 1
    for m in pat.finditer(s, start):
        depth += 1 if m.group(1) == "begin" else -1
        if depth == 0:
            return m.start(), m.end()
    raise GenerationError(f"\\begin{{{name}}} without matching \\end{{{name}}}")


def split_top_level(s: str, sep: str) -> list[str]:
    """Split on `sep` ('&' or '\\\\') outside braces and nested environments."""
    parts, buf, depth, env_depth, i = [], [], 0, 0, 0
    while i < len(s):
        if s.startswith("\\begin{", i):
            env_depth += 1
        elif s.startswith("\\end{", i):
            env_depth -= 1
        c = s[i]
        if sep == "\\\\" and s.startswith("\\\\", i) and depth == 0 and env_depth == 0:
            parts.append("".join(buf))
            buf = []
            i += 2
            _, i = read_optional(s, i)
            continue
        if c == "\\":
            buf.append(s[i:i + 2])
            i += 2
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
        if c == sep and depth == 0 and env_depth == 0:
            parts.append("".join(buf))
            buf = []
            i += 1
            continue
        buf.append(c)
        i += 1
    parts.append("".join(buf))
    return parts


def split_items(content: str) -> list[tuple[str | None, str]]:
    """Split list-environment content into (optional label, body) per top-level \\item."""
    items: list[tuple[str | None, str]] = []
    depth = env_depth = 0
    i, cur_start, cur_label = 0, None, None
    item_re = re.compile(r"\\item(?![A-Za-z])")
    while i < len(content):
        if content.startswith("\\begin{", i):
            env_depth += 1
        elif content.startswith("\\end{", i):
            env_depth -= 1
        c = content[i]
        if depth == 0 and env_depth == 0 and item_re.match(content, i):
            if cur_start is not None:
                items.append((cur_label, content[cur_start:i]))
            j = i + len("\\item")
            cur_label, j = read_optional(content, j)
            cur_start, i = j, j
            continue
        if c == "\\":
            i += 2
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
        i += 1
    if cur_start is not None:
        items.append((cur_label, content[cur_start:]))
    return items


def collapse_ws(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def slugify(s: str, max_words: int = 4) -> str:
    words = re.findall(r"[a-z0-9]+", s.lower())
    return "-".join(words[:max_words]) or "block"


