# Inputs: main.aux, refs.bib, numbers.json
# ---------------------------------------------------------------------------

@dataclass
class LabelInfo:
    number: str
    page: str
    title: str
    anchor: str

    @property
    def kind(self) -> str:
        return self.anchor.split(".", 1)[0].lower() if self.anchor else ""


def parse_aux(path: Path) -> dict[str, LabelInfo]:
    labels: dict[str, LabelInfo] = {}
    if not path.exists():
        return labels
    text = path.read_text(encoding="utf-8", errors="replace")
    for m in re.finditer(r"\\newlabel\{", text):
        try:
            key, j = read_group(text, m.end() - 1)
            grp, _ = read_group(text, skip_ws(text, j))
        except GenerationError:
            continue
        if key.endswith("@cref"):
            continue
        parts, k = [], 0
        while k < len(grp):
            if grp[k] == "{":
                c, k = read_group(grp, k)
                parts.append(c)
            else:
                k += 1
        parts += [""] * (4 - len(parts))
        labels[key] = LabelInfo(parts[0].strip(), parts[1], parts[2], parts[3])
    return labels


@dataclass
class BibEntry:
    kind: str
    key: str
    fields: dict[str, str]


def parse_bib(path: Path) -> list[BibEntry]:
    if not path.exists():
        return []
    text = path.read_text(encoding="utf-8")
    entries = []
    for m in re.finditer(r"@(\w+)\s*\{", text):
        kind = m.group(1).lower()
        if kind in ("comment", "preamble", "string"):
            continue
        body, _ = read_group(text, m.end() - 1)
        key, _, rest = body.partition(",")
        fields: dict[str, str] = {}
        i = 0
        while i < len(rest):
            fm = re.compile(r"\s*([A-Za-z][\w-]*)\s*=\s*").match(rest, i)
            if not fm:
                i += 1
                continue
            name, i = fm.group(1).lower(), fm.end()
            if i < len(rest) and rest[i] == "{":
                val, i = read_group(rest, i)
            elif i < len(rest) and rest[i] == '"':
                j = i + 1
                while j < len(rest) and rest[j] != '"':
                    j = read_group(rest, j)[1] if rest[j] == "{" else j + 1
                val, i = rest[i + 1:j], j + 1
            else:
                vm = re.compile(r"[^,]*").match(rest, i)
                val, i = vm.group(0).strip(), vm.end()
            fields[name] = collapse_ws(val)
        entries.append(BibEntry(kind, key.strip(), fields))
    return entries


def _unbrace(s: str) -> str:
    return re.sub(r"[{}]", "", s).strip()


def bib_short_name(entry: BibEntry) -> str:
    raw = entry.fields.get("author") or entry.fields.get("editor") or ""
    authors = [a for a in split_bib_authors(raw) if a]
    lasts = []
    for a in authors:
        if a.startswith("{") and a.endswith("}") and read_group(a, 0)[1] == len(a):
            lasts.append(_unbrace(a))            # corporate author {Ecma International}
        elif "," in a:
            lasts.append(_unbrace(a.split(",", 1)[0]))
        else:
            lasts.append(_unbrace(a.split()[-1]))
    lasts = [latex_to_plain(x) for x in lasts]
    year = entry.fields.get("year", "n.d.")
    if not lasts:
        return f"{entry.key} {year}"
    if len(lasts) == 1:
        return f"{lasts[0]} {year}"
    if len(lasts) == 2:
        return f"{lasts[0]} & {lasts[1]} {year}"
    return f"{lasts[0]} et al. {year}"


def split_bib_authors(raw: str) -> list[str]:
    out, buf, depth = [], [], 0
    tokens = re.split(r"(\s+and\s+|[{}])", raw)
    for t in tokens:
        if t == "{":
            depth += 1
        elif t == "}":
            depth -= 1
        if depth == 0 and re.fullmatch(r"\s+and\s+", t or ""):
            out.append("".join(buf).strip())
            buf = []
        else:
            buf.append(t or "")
    out.append("".join(buf).strip())
    return out


def bib_reference_string(entry: BibEntry) -> str:
    f = entry.fields
    title = latex_to_plain(_unbrace(f.get("title", entry.key)))
    parts = []
    if f.get("journal"):
        s = latex_to_plain(_unbrace(f["journal"]))
        if f.get("volume"):
            s += " " + f["volume"]
            if f.get("number"):
                s += f"({f['number']})"
            if f.get("pages"):
                s += ":" + f["pages"].replace("--", "-")
        elif f.get("pages"):
            s += " " + f["pages"].replace("--", "-")
        parts.append(s)
    elif f.get("booktitle"):
        parts.append(latex_to_plain(_unbrace(f["booktitle"])) + (f" {f['year']}" if f.get("year") else ""))
    elif entry.kind == "techreport":
        parts.append(latex_to_plain(_unbrace(f.get("number") or f.get("institution", ""))))
    if f.get("note"):
        parts.append(latex_to_plain(_unbrace(f["note"])))
    m = re.search(r"arxiv\.org/abs/([\w.]+)", f.get("url", ""))
    if m and not any(m.group(1) in p for p in parts):
        parts.append(f"arXiv:{m.group(1)}")
    sep = " " if title.endswith(("?", "!", ".")) else ". "
    return title + (sep + ", ".join(p for p in parts if p) if any(parts) else "")


class Numbers:
    """Lazy numbers.json lookup for \\val{key}; any problem is a hard error naming the key."""

    def __init__(self, path: Path):
        self.path = path
        self._values: dict | None = None

    def get(self, key: str) -> str:
        if self._values is None:
            if not self.path.exists():
                raise GenerationError(f"\\val{{{key}}} is used but {self.path} does not exist")
            data = json.loads(self.path.read_text(encoding="utf-8"))
            values = data.get("values") if isinstance(data, dict) else None
            if not isinstance(values, dict):
                raise GenerationError(f"{self.path}: top-level 'values' object missing (needed for \\val{{{key}}})")
            self._values = values
        if key not in self._values:
            raise GenerationError(f"\\val{{{key}}}: key {key!r} not found in {self.path}")
        entry = self._values[key]
        value = entry.get("value") if isinstance(entry, dict) else entry
        if not isinstance(value, str) or not value:
            raise GenerationError(f"\\val{{{key}}}: {self.path.name} has no non-empty string 'value' for it")
        return value


